INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 13, 'theory', 'Quiz: red-black trees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 0, 'What do the rules of a red-black tree guarantee?', '["All leaves are at the same depth", "A height of at most 2·log₂(n + 1)", "A height of exactly log₂ n", "No rotations during insertion"]', 1, 'The black height is the same on all paths and reds never come in a row, so the longest path is at most twice as long as the shortest.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 1, 'A new node is inserted into a red-black tree. What color is it painted?', '["Black", "Red", "The color of its parent", "The color of its uncle"]', 1, 'A red node doesn''t change the black heights on any path and can break only the rule "no two reds in a row", which is easier to fix.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 2, 'The parent of the new node is red, and the uncle is red too. What do we do?', '["Rotate the grandparent", "Recolor the parent and uncle black and the grandparent red, then move up to the grandparent", "Delete the node", "Nothing"]', 1, 'Black heights don''t change and there are no rotations, but the red grandparent may now sit under a red parent, so we repeat the step for it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 3, 'Which rotations are needed if the uncle is black and the new node is the right child of a left parent?', '["One right rotation of the grandparent", "A left rotation of the parent, then a right rotation of the grandparent with recoloring", "Two left rotations", "No rotations"]', 1, 'This is a kink: rotating the parent turns it into a line, and then a rotation of the grandparent with recoloring finishes the insertion, with at most two rotations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 4, 'What is the practical difference between an AVL tree and a red-black tree?', '["AVL searches faster (stricter balance), red-black is cheaper to rebalance on insertions and deletions", "AVL uses no rotations", "A red-black tree doesn''t need balancing", "There is no difference"]', 0, 'AVL keeps the height around 1.44 log n, red-black up to 2 log n, but red-black makes fewer rotations, especially on deletion.');
